macro_rules! nghttp2_send_callback {
    () => {
        # [doc = " @functypedef"] # [doc = ""] # [doc = " Callback function invoked when |session| wants to send data to the"] # [doc = " remote peer.  The implementation of this function must send at most"] # [doc = " |length| bytes of data stored in |data|.  The |flags| is currently"] # [doc = " not used and always 0. It must return the number of bytes sent if"] # [doc = " it succeeds.  If it cannot send any single byte without blocking,"] # [doc = " it must return :enum:`NGHTTP2_ERR_WOULDBLOCK`.  For other errors,"] # [doc = " it must return :enum:`NGHTTP2_ERR_CALLBACK_FAILURE`.  The"] # [doc = " |user_data| pointer is the third argument passed in to the call to"] # [doc = " `nghttp2_session_client_new()` or `nghttp2_session_server_new()`."] # [doc = ""] # [doc = " This callback is required if the application uses"] # [doc = " `nghttp2_session_send()` to send data to the remote endpoint.  If"] # [doc = " the application uses solely `nghttp2_session_mem_send()` instead,"] # [doc = " this callback function is unnecessary."] # [doc = ""] # [doc = " To set this callback to :type:`nghttp2_session_callbacks`, use"] # [doc = " `nghttp2_session_callbacks_set_send_callback()`."] # [doc = ""] # [doc = " .. note::"] # [doc = ""] # [doc = "   The |length| may be very small.  If that is the case, and"] # [doc = "   application disables Nagle algorithm (``TCP_NODELAY``), then just"] # [doc = "   writing |data| to the network stack leads to very small packet,"] # [doc = "   and it is very inefficient.  An application should be responsible"] # [doc = "   to buffer up small chunks of data as necessary to avoid this"] # [doc = "   situation."] pub type nghttp2_send_callback = :: std :: option :: Option < unsafe extern "C" fn (session : * mut nghttp2_session , data : * const u8 , length : usize , flags : :: std :: os :: raw :: c_int , user_data : * mut :: std :: os :: raw :: c_void ,) -> isize , > ;
    };
}

nghttp2_send_callback!()